import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Boot modes","description":"","frontmatter":{},"headers":[],"relativePath":"manual/boot-modes.md","filePath":"manual/boot-modes.md"}'),i={name:"manual/boot-modes.md"};function n(l,e,d,r,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="boot-modes" tabindex="-1">Boot modes <a class="header-anchor" href="#boot-modes" aria-label="Permalink to &quot;Boot modes&quot;">​</a></h1><h2 id="bios-legacy" tabindex="-1">BIOS (legacy) <a class="header-anchor" href="#bios-legacy" aria-label="Permalink to &quot;BIOS (legacy)&quot;">​</a></h2><p>The default: GRUB i386-pc from the ISO, loading the multiboot2 kernel with its embedded module chain. The same loader is what <code>install</code> / <code>abdisk</code> write to a disk, so an installed system boots exactly like the ISO it came from.</p><h2 id="uefi" tabindex="-1">UEFI <a class="header-anchor" href="#uefi" aria-label="Permalink to &quot;UEFI&quot;">​</a></h2><p>The ISO carries an EFI boot leg; OVMF boots it under QEMU:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512M -bios OVMF.fd -cdrom opencube-3.0.0.iso \\</span></span>
<span class="line"><span>    -boot d</span></span></code></pre></div><p>On real hardware pick the EFI entry in the firmware boot menu. The A/B slot logic (below) is identical in both modes.</p><h2 id="the-a-b-slot-menu" tabindex="-1">The A/B slot menu <a class="header-anchor" href="#the-a-b-slot-menu" aria-label="Permalink to &quot;The A/B slot menu&quot;">​</a></h2><p>On an A/B disk, GRUB reads the boot flag and offers:</p><ul><li>the <strong>active slot</strong> (default, auto-selected),</li><li><strong>force-slot-A</strong> and <strong>force-slot-B</strong> entries - the manual override when the active slot misbehaves.</li></ul><p>The flag lives on the A/B disk; <code>update status</code> shows which slot is running and which boots next, and <code>update rollback</code> flips it from inside the system.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>An ISO boot runs from RAM: everything resets on reboot. For a persistent system:</p><ol><li><code>install &lt;disk&gt;</code> - partition + copy the running kernel + GRUB + /etc volume, single-system shape; or</li><li><code>abdisk &lt;disk&gt;</code> (via <code>disk-tool</code>&#39;s A/B manager) - the two-slot update-disk shape, which OTA updates target.</li></ol><p>Attach a config volume (<code>etc.img</code>, a FAT32 disk with <code>opencube.conf</code> and optionally <code>ssh_host_key</code>) to carry settings and host keys across reboots without installing.</p><h2 id="boot-self-tests" tabindex="-1">Boot self-tests <a class="header-anchor" href="#boot-self-tests" aria-label="Permalink to &quot;Boot self-tests&quot;">​</a></h2><p>Every boot runs the self-test chain before the shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exception self-test: 3/3</span></span>
<span class="line"><span>boot complete....... OK</span></span></code></pre></div><p>A boot that reaches <code>ush&gt;</code> has already proven its exception stack, timer and console. The regression gate asserts the same lines plus a live framebuffer check (BUG #66), so &quot;it booted&quot; is a tested statement, not a hope.</p>`,19)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
